// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class LmdbPlanAssumptionsTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI Q = VF.createIRI("urn:a");

	@Test
	void unstampedTreeHasNoAssumptions() {
		LmdbPlanAssumptions assumptions = LmdbPlanAssumptions.collect(new QueryRoot(pattern()));

		assertSame(LmdbPlanAssumptions.NONE, assumptions);
		assertTrue(assumptions.none());
		assertEquals(LmdbPlanAssumptions.NONE_TOKEN, assumptions.describe());
	}

	@Test
	void collectFindsCommittedSnapshotAndGuaranteeStamps() {
		BindingSetAssignment storedTermAnchor = new BindingSetAssignment();
		LmdbPlanAssumptions.stampCommittedSnapshot(storedTermAnchor);
		BindingSetAssignment guaranteeAnchor = new BindingSetAssignment();
		LmdbPlanAssumptions.stampGuaranteePredicate(guaranteeAnchor, P);
		BindingSetAssignment secondGuaranteeAnchor = new BindingSetAssignment();
		LmdbPlanAssumptions.stampGuaranteePredicate(secondGuaranteeAnchor, Q);
		QueryRoot root = new QueryRoot(new Join(new Join(storedTermAnchor, guaranteeAnchor),
				new Join(secondGuaranteeAnchor, pattern())));

		LmdbPlanAssumptions assumptions = LmdbPlanAssumptions.collect(root);

		assertTrue(assumptions.committedSnapshotDependent());
		assertTrue(assumptions.guaranteeDependent());
		assertEquals(Set.of(P, Q), assumptions.guaranteePredicates());
		assertEquals(List.of(Q, P), List.copyOf(assumptions.guaranteePredicates()),
				"guarantee predicates are ordered by IRI for deterministic descriptions");
		assertEquals("committedSnapshot,guarantee:urn:a,guarantee:urn:p", assumptions.describe());
	}

	@Test
	void guaranteeOnlyAssumptionsAreNotCommittedSnapshotDependent() {
		BindingSetAssignment guaranteeAnchor = new BindingSetAssignment();
		LmdbPlanAssumptions.stampGuaranteePredicate(guaranteeAnchor, P);

		LmdbPlanAssumptions assumptions = LmdbPlanAssumptions.collect(new QueryRoot(new Join(guaranteeAnchor,
				pattern())));

		assertFalse(assumptions.committedSnapshotDependent());
		assertTrue(assumptions.guaranteeDependent());
		assertFalse(assumptions.none());
		assertEquals("guarantee:urn:p", assumptions.describe());
	}

	@Test
	void annotateStampsTheQueryRootAndItsObservableArg() {
		QueryRoot root = new QueryRoot(pattern());
		LmdbPlanAssumptions assumptions = new LmdbPlanAssumptions(true, Set.of(P));

		assumptions.annotate(root);

		assertEquals("committedSnapshot,guarantee:urn:p",
				root.getStringMetricPlanned(LmdbPlanAssumptions.PLAN_ASSUMPTIONS_METRIC));
		assertEquals("committedSnapshot,guarantee:urn:p",
				root.getArg().getStringMetricPlanned(LmdbPlanAssumptions.PLAN_ASSUMPTIONS_METRIC));
	}

	private static StatementPattern pattern() {
		return new StatementPattern(Var.of("s"), Var.of("p", P), Var.of("o"));
	}
}
